    private fun symbol(name: String, vararg pathData: String): ImageVector =
        ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 960f, viewportHeight = 960f).apply {
            group(translationY = 960f) {
                pathData.forEach { d -> addPath(addPathNodes(d), fill = SolidColor(Color.Black)) }
            }
        }.build()
